	// Changes is the entity-level change list for the range, already carrying the
	// graph's dependent counts.
	Changes []Change `json:"changes"`

	// Callers maps an entity to the call sites and type uses that reach it, drawn
	// from the committed graph — code written before this change existed.
	Callers map[string][]Evidence `json:"-"`

	// Tests maps an entity to the tests the resolver believes verify it.
	Tests map[string][]Evidence `json:"-"`

	// Cochanges maps a changed file path to the files git says normally change
	// with it, with how often.
	Cochanges map[string][]Cochange `json:"-"`

	// Clones maps an entity to its near-duplicate bodies elsewhere in the repo.
	Clones map[string][]EntityRef `json:"-"`

	// ChangedFiles is the set of files the range touched, so the companion check
	// can ask what is MISSING from it.
	ChangedFiles map[string]bool `json:"-"`

	// Unavailable records checks collect could not gather evidence for, and why.
	// Populated by collect, consumed by the check functions, which turn each entry
	// into a NotRun CheckResult rather than an empty finding list. The difference
	// matters: an empty finding list means "looked, found nothing".
	Unavailable map[CheckID]string `json:"-"`
}

// Cochange is one git observation: how often another file changed in the same
// commit as the subject file, out of how many commits observed.
type Cochange struct {
	Path     string `json:"path"`
	Together int    `json:"together"`
	Observed int    `json:"observed"`
}

// Rate is how often the two files moved together, in [0,1].
func (c Cochange) Rate() float64 {
	if c.Observed <= 0 {
		return 0
	}
	return float64(c.Together) / float64(c.Observed)
}

// Report is the finished decision: what was judged, what a human should read,
// and why the verdict is what it is.
type Report struct {
	Repo string `json:"repo,omitempty"`
	Base string `json:"base"`
	Head string `json:"head"`

	// Verdict and its exit code are the enforceable half of the product.
	Verdict  Verdict `json:"verdict"`
	ExitCode int     `json:"exit_code"`

	// Reasons state, in the report itself, WHY the verdict is what it is, so the
	// tool is never a black box.
	Reasons []string `json:"reasons,omitempty"`

	// TotalEntities is every entity the range touched, including the quiet ones
	// left out of Review.
	TotalEntities int `json:"total_entities"`
	// Review is the ranked read-this-first list. Sorted; never map-ordered.
	Review []ReviewItem `json:"review"`
	// QuietCount is how many entities had nothing to say, summarised as a count
	// rather than printed. The full list is available behind --all.
	QuietCount int `json:"quiet_count"`

	// Checks reports every check and whether it ran, in CheckOrder.
	Checks []CheckResult `json:"checks"`
}

// Ran reports whether a named check contributed evidence to this report.
func (r Report) Ran(id CheckID) bool {
	for _, check := range r.Checks {
		if check.ID == id {
			return check.Ran
		}
	}
	return false
}

package gate

import "fmt"

// Risk answers: what breaks if this changed?
//
// The evidence is entirely code the change did not write — the dependent count
// the graph computed from the committed tree, and the call sites behind it. That
// is the property the whole product rests on: an agent cannot talk its way past
// this check, because the check never reads anything the agent produced.
func Risk(input Input) CheckResult {
	if reason, missing := input.Unavailable[CheckRisk]; missing {
		// Cap at continue, never revert: with no dependent counts every change
		// looks harmless, and a check that did not run must not be allowed to
		// produce a keep either.
		return NotRun(CheckRisk, reason, VerdictContinue)
	}

	result := CheckResult{ID: CheckRisk, Ran: true}
	for _, change := range input.Changes {
		if change.Dependents == 0 {
			// Nothing points at it. Not evidence of safety, but nothing for a
			// reviewer to read either, so it stays out of the review order.
			continue
		}
		finding := Finding{
			Check:   CheckRisk,
			Subject: change.EntityRef,
			Summary: riskSummary(change),
			// Informational on its own. Whether a dependent count means keep,
			// continue or revert depends on coverage, and no single check may
			// answer a question that needs two — see Decide.
			Floor: VerdictKeep,
		}
		evidence := append([]Evidence(nil), input.Callers[change.Key()]...)
		SortEvidence(evidence)
		finding.Evidence = evidence
		result.Findings = append(result.Findings, finding)
	}
	sortFindings(result.Findings)
	return result
}

// riskSummary states the fact, not the advice: what changed and how many things
// the graph can see that depend on it.
func riskSummary(change Change) string {
	return fmt.Sprintf("%s · %d dependent%s", change.Change, change.Dependents, plural(change.Dependents))
}

func plural(n int) string {
	if n == 1 {
		return ""
	}
	return "s"
}

package gate

// Coverage answers: did anything verify this?
//
// PHASE 0 STUB — the signature and the not-run contract are final; the body is
// Lane B's. Until it is written the check reports itself as not run, which under
// the degradation rule caps the verdict at continue. That is the correct
// behaviour for a missing input, and it means the rest of the pipeline can be
// built and demonstrated before this exists.
//
// When implementing: the repo's own test resolver (internal/sem/search_verify.go)
// is NOT reachable from here — every derivation in it is unexported and keyed off
// search results rather than a diff. Resolve tests from Input.Tests, which collect
// fills using file-mirror conventions, and record the evidence so a reviewer can
// open the test that supposedly covers the change.
func Coverage(input Input) CheckResult {
	if reason, missing := input.Unavailable[CheckCoverage]; missing {
		return NotRun(CheckCoverage, reason, VerdictContinue)
	}
	return NotRun(CheckCoverage, "not implemented yet", VerdictContinue)
}

// coverageOf reports what the coverage check concluded about one entity. It is
// the single place the merged report reads coverage from, so the distinction
// between "looked and found nothing" and "could not look" is made exactly once.
func coverageOf(input Input, check CheckResult, ref EntityRef) (CoverageState, []Evidence) {
	if !check.Ran {
		return CoverageUnknown, nil
	}
	tests := append([]Evidence(nil), input.Tests[ref.Key()]...)
	if len(tests) == 0 {
		return CoverageUnchecked, nil
	}
	SortEvidence(tests)
	return CoverageCovered, tests
}

package gate

// CompanionThreshold and CompanionMinObservations are the hand-tuned constants
// behind the companion gap. They are printed in the report rather than hidden,
// because they are a judgement call and not a learned value: a file that moved
// with the subject in at least this share of at least this many observed commits
// is treated as a companion.
const (
	CompanionThreshold       = 0.70
	CompanionMinObservations = 5
)

// Companions answers: what normally changes with this, but did not this time?
//
// PHASE 0 STUB — signature and not-run contract are final; the body is Lane C's.
//
// This is the check that finds FORGOTTEN work, and it is the reason Gate is not
// just a nicer diff: the evidence is not in the change. It comes from git history
// older than the session, via gitutil.FileCochanges, which collect places in
// Input.Cochanges. A finding here sets Floor VerdictContinue on its own — a file
// that has accompanied this one in 14 of the last 15 commits and is absent now is
// worth a human look regardless of what the coverage check thinks.
func Companions(input Input) CheckResult {
	if reason, missing := input.Unavailable[CheckCompanions]; missing {
		// Cap at keep: a missing companion check removes a reason to worry, it
		// does not add one, so it must not hold the verdict above keep on its own.
		return NotRun(CheckCompanions, reason, VerdictKeep)
	}
	return NotRun(CheckCompanions, "not implemented yet", VerdictKeep)
}

package gate

// CompanionThreshold and CompanionMinObservations are the hand-tuned constants
// behind the companion gap. They are printed in the report rather than hidden,
// because they are a judgement call and not a learned value: a file that moved
// with the subject in at least this share of at least this many observed commits
// is treated as a companion.
const (
	CompanionThreshold       = 0.70
	CompanionMinObservations = 5
)

// Companions answers: what normally changes with this, but did not this time?
//
// PHASE 0 STUB — signature and not-run contract are final; the body is Lane C's.
//
// This is the check that finds FORGOTTEN work, and it is the reason Gate is not
// just a nicer diff: the evidence is not in the change. It comes from git history
// older than the session, via gitutil.FileCochanges, which collect places in
// Input.Cochanges. A finding here sets Floor VerdictContinue on its own — a file
// that has accompanied this one in 14 of the last 15 commits and is absent now is
// worth a human look regardless of what the coverage check thinks.
func Companions(input Input) CheckResult {
	if reason, missing := input.Unavailable[CheckCompanions]; missing {
		return NotRun(CheckCompanions, reason, noCeiling)
	}
	return NotRun(CheckCompanions, "not implemented yet", noCeiling)
}

// noCeiling is the empty Cap: this check imposes no ceiling when it does not run.
//
// Only risk and coverage cap the verdict, and the reason is directional. Those
// two are the checks that can EXCUSE a change — a low dependent count or a
// passing test is what moves a verdict toward keep — so losing them means Gate no
// longer knows the change is fine, and it must stop short of saying so. The
// companion and clone checks only ever accuse. Losing one removes a reason to
// worry; it never invents a reason to relax, so capping on them would suppress
// findings the checks that DID run legitimately produced.
const noCeiling Verdict = ""

package gate

// Clones answers: are there near-duplicate copies that did not get the fix?
//
// PHASE 0 STUB — signature and not-run contract are final; the body is Lane C's.
//
// Cheaper than the plan assumed: the graph already emits a SIMILAR_TO relation
// for near-duplicate bodies (MinHash >= 0.82, see internal/sem/provider.go), so
// collect fills Input.Clones from a graph query rather than from a clone detector
// written here. The finding to produce is "you fixed one copy, N others still
// have it": for each changed entity, its SIMILAR_TO peers whose own files are
// absent from Input.ChangedFiles.
func Clones(input Input) CheckResult {
	if reason, missing := input.Unavailable[CheckClones]; missing {
		return NotRun(CheckClones, reason, noCeiling)
	}
	return NotRun(CheckClones, "not implemented yet", noCeiling)
}

package gate

import "sort"

// Evaluate is the whole pipeline: run every check over the collected evidence,
// merge it into a review order, and decide. It is the only function internal/cli
// needs to call, and it is pure — the same Input always produces the same Report,
// byte for byte, which is what lets Gate block a push.
func Evaluate(input Input) Report {
	checks := RunChecks(input)
	report := Build(input, checks)
	Decide(&report)
	return report
}

// RunChecks runs the four checks in CheckOrder. The order is fixed rather than
// derived from a map so the report reads the same way every run, and the checks
// are independent by design: adding a fifth evidence source is a new file plus a
// line here, not a change to anything that already works.
func RunChecks(input Input) []CheckResult {
	return []CheckResult{
		Risk(input),
		Coverage(input),
		Companions(input),
		Clones(input),
	}
}

// Build merges the checks into one entity-per-row review order.
//
// A check that did not run contributes nothing: its findings are dropped rather
// than trusted, because a check that reports itself as not-run may have produced
// a partial finding list before it gave up, and half an answer read as a whole
// one is how a gate starts lying.
func Build(input Input, checks []CheckResult) Report {
	report := Report{
		Repo:          input.Repo,
		Base:          input.Base,
		Head:          input.Head,
		TotalEntities: len(input.Changes),
		Checks:        orderChecks(checks),
	}

	coverageCheck := findCheck(report.Checks, CheckCoverage)

	// Findings are grouped by their subject so one entity is one row, no matter
	// how many checks had something to say about it.
	bySubject := make(map[string][]Finding)
	for _, check := range report.Checks {
		if !check.Ran {
			continue
		}
		for _, finding := range check.Findings {
			key := finding.Subject.Key()
			bySubject[key] = append(bySubject[key], finding)
		}
	}

	// Ranged over input.Changes, NOT over bySubject: a map range would order the
	// review differently on every run.
	for _, change := range input.Changes {
		state, evidence := coverageOf(input, coverageCheck, change.EntityRef)
		item := ReviewItem{
			Change:           change,
			Coverage:         state,
			CoverageEvidence: evidence,
			Findings:         bySubject[change.Key()],
		}
		sortFindings(item.Findings)
		if item.Quiet() {
			report.QuietCount++
			continue
		}
		report.Review = append(report.Review, item)
	}
	sortReview(report.Review)
	return report
}

// orderChecks returns the results in CheckOrder, so a caller that assembles them
// in some other order still produces an identically ordered report.
func orderChecks(checks []CheckResult) []CheckResult {
	ordered := make([]CheckResult, 0, len(checks))
	for _, id := range CheckOrder {
		for _, check := range checks {
			if check.ID == id {
				ordered = append(ordered, check)
			}
		}
	}
	// Anything not in CheckOrder is a check someone added without registering it.
	// Keep it rather than drop it, appended in the caller's order, so it shows up
	// in the report instead of vanishing.
	for _, check := range checks {
		if !knownCheck(check.ID) {
			ordered = append(ordered, check)
		}
	}
	return ordered
}

func knownCheck(id CheckID) bool {
	for _, known := range CheckOrder {
		if known == id {
			return true
		}
	}
	return false
}

func findCheck(checks []CheckResult, id CheckID) CheckResult {
	for _, check := range checks {
		if check.ID == id {
			return check
		}
	}
	return CheckResult{ID: id}
}

// sortReview puts the review order in the order a reviewer should read it, with
// a total ordering all the way down so two runs cannot differ.
//
// Blocking rows come first — the ones where something that breaks callers has
// dependents and nothing verifies it — because those are the rows that decide the
// verdict. After that it is dependent count, then how much was found, then the
// location, which is the tie-break that makes the sort total.
func sortReview(items []ReviewItem) {
	sort.SliceStable(items, func(i, j int) bool {
		left, right := items[i], items[j]
		if blocking(left) != blocking(right) {
			return blocking(left)
		}
		if left.Change.Dependents != right.Change.Dependents {
			return left.Change.Dependents > right.Change.Dependents
		}
		if len(left.Findings) != len(right.Findings) {
			return len(left.Findings) > len(right.Findings)
		}
		if left.Change.Path != right.Change.Path {
			return left.Change.Path < right.Change.Path
		}
		if left.Change.Line != right.Change.Line {
			return left.Change.Line < right.Change.Line
		}
		return left.Change.Name < right.Change.Name
	})
}

// blocking reports the revert condition for one row: something that breaks code
// written before this change, with dependents, and nothing that verifies it.
//
// CoverageUnknown counts as unverified HERE on purpose. This function only ranks;
// it does not judge. Decide applies the degradation rule afterwards, so a missing
// coverage check still floats the riskiest rows to the top of the reading order
// while being forbidden from turning them into a revert.
func blocking(item ReviewItem) bool {
	return item.Change.Change.BreaksCallers() &&
		item.Change.Dependents > 0 &&
		item.Coverage != CoverageCovered
}

// sortFindings gives a finding list a total order for rendering.
func sortFindings(findings []Finding) {
	sort.SliceStable(findings, func(i, j int) bool {
		left, right := findings[i], findings[j]
		if left.Check != right.Check {
			return checkRank(left.Check) < checkRank(right.Check)
		}
		if left.Subject.Path != right.Subject.Path {
			return left.Subject.Path < right.Subject.Path
		}
		if left.Subject.Line != right.Subject.Line {
			return left.Subject.Line < right.Subject.Line
		}
		if left.Subject.Name != right.Subject.Name {
			return left.Subject.Name < right.Subject.Name
		}
		return left.Summary < right.Summary
	})
}

// checkRank orders findings by CheckOrder rather than alphabetically, so a row
// reads risk first and the cheaper observations after.
func checkRank(id CheckID) int {
	for index, known := range CheckOrder {
		if known == id {
			return index
		}
	}
	return len(CheckOrder)
}

package gate

import "fmt"

// VerdictRules is the rule set, in the words the tool judges by, printed in
// every run so Gate is never a black box. If the code below and these lines ever
// disagree, the lines are the bug.
func VerdictRules() []string {
	return []string{
		"keep     (exit 0)  nothing with dependents changed, and no check found anything",
		"continue (exit 1)  something has dependents, or a check found something, or new code has no test",
		"revert   (exit 2)  something that breaks callers has dependents AND no covering test",
		"unusable (exit 5)  Gate ran but could not get evidence - do not build on this report",
		"",
		"A check that did not run is reported as not-run, never as a failure, and can",
		"never push the verdict upward: missing risk or coverage evidence caps the",
		"verdict at continue, and missing both makes the run unusable.",
	}
}

// Decide sets the verdict, exit code and reasons on a built report.
//
// It is the only place that reads two checks at once. The revert rule needs risk
// AND coverage together — "has dependents" is one check and "nothing verifies it"
// is another — so it cannot live inside either of them without one check reaching
// into the other, which the one-way data flow forbids.
func Decide(report *Report) {
	verdict, reasons := judge(*report)
	verdict, reasons = degrade(*report, verdict, reasons)

	report.Verdict = verdict
	report.ExitCode = verdict.ExitCode()
	report.Reasons = reasons
}

// judge applies the rules as if every check had run. The degradation rule is
// applied afterwards, separately, so that the two concerns stay legible: this
// function answers "what does the evidence say", degrade answers "how much of the
// evidence do we actually have".
func judge(report Report) (Verdict, []string) {
	verdict := VerdictKeep
	var reasons []string
	seen := make(map[string]bool)

	addReason := func(text string) {
		if seen[text] {
			return
		}
		seen[text] = true
		reasons = append(reasons, text)
	}

	if report.TotalEntities == 0 {
		return VerdictKeep, []string{"no entity-level changes in this range"}
	}

	// report.Review is already sorted, so the reasons come out in a fixed order.
	for _, item := range report.Review {
		change := item.Change
		covered := item.Coverage == CoverageCovered

		// The revert rule. CoverageUnknown is treated as uncovered here and
		// corrected by degrade, rather than being special-cased twice.
		if change.Change.BreaksCallers() && change.Dependents > 0 && !covered {
			verdict = worseOf(verdict, VerdictRevert)
			addReason(fmt.Sprintf("%s at %s is %s with %d dependent%s and no covering test",
				change.Name, change.Location(), change.Change, change.Dependents, plural(change.Dependents)))
			continue
		}

		if change.Dependents > 0 {
			verdict = worseOf(verdict, VerdictContinue)
			addReason(fmt.Sprintf("%s at %s has %d dependent%s",
				change.Name, change.Location(), change.Dependents, plural(change.Dependents)))
		}

		// New code that nothing verifies. Deliberately not a revert: there are no
		// dependents to break yet, but there is also nothing holding it up.
		if change.Change == ChangeAdded && item.Coverage == CoverageUnchecked {
			verdict = worseOf(verdict, VerdictContinue)
			addReason(fmt.Sprintf("%s at %s is new and has no test", change.Name, change.Location()))
		}

		// A finding may raise the floor on its own — a companion gap does, because
		// forgotten work is worth a look whatever the tests say.
		for _, finding := range item.Findings {
			if finding.Floor.severity() <= verdict.severity() {
				continue
			}
			verdict = worseOf(verdict, finding.Floor)
			addReason(fmt.Sprintf("%s: %s (%s)", finding.Subject.Name, finding.Summary, finding.Check))
		}
	}

	return verdict, reasons
}

// degrade applies the degradation rule: a check that did not run can never push
// the verdict upward.
//
// Without it, a coverage check that failed to run would mean nothing has a
// covering test, so every risky change would read as revert. That is not
// strictness — it is a false accusation caused by a missing input.
func degrade(report Report, verdict Verdict, reasons []string) (Verdict, []string) {
	riskRan := report.Ran(CheckRisk)
	coverageRan := report.Ran(CheckCoverage)

	// Both of the checks that can excuse a change are gone. Gate has an opinion
	// about nothing, and says so rather than guessing.
	if !riskRan && !coverageRan {
		return VerdictUnusable, append(reasons,
			"the risk and coverage checks both did not run - there is not enough evidence to judge this range")
	}

	for _, check := range report.Checks {
		if check.Ran || check.Cap == noCeiling {
			continue
		}
		if verdict.severity() <= check.Cap.severity() {
			continue
		}
		verdict = check.Cap
		reasons = append(reasons, fmt.Sprintf(
			"the %s check did not run (%s), so the verdict is capped at %s",
			check.ID, notRunReason(check), check.Cap))
	}
	return verdict, reasons
}

func notRunReason(check CheckResult) string {
	if check.Reason == "" {
		return "no reason given"
	}
	return check.Reason
}

